package serializers

import (
	"fmt"
	"io"

	"google.golang.org/protobuf/proto"

	pbv2 "serializer-benchmark-go/gen/pbv2"
	"serializer-benchmark-go/model"
	modelv2 "serializer-benchmark-go/model/v2"
)

// omniWireMessage is satisfied by every static codec generated by protoc-gen-omnibuf-go.
type omniWireMessage interface {
	proto.Message
	MarshalOmniBufAppend(dst []byte) []byte
	UnmarshalOmniBuf(data []byte, zeroCopy bool) error
}

// omniBuf uses protoc-gen-omnibuf-go static codecs (https://github.com/omnibuf/omnibuf-go).
type omniBuf struct {
	msg     omniWireMessage
	dst     omniWireMessage
	serBuf  []byte
	fxName  string
	batch   bool
	project bool
}

func newOmniBuf() *omniBuf { return &omniBuf{} }

func (s *omniBuf) Name() string           { return "omnibuf" }
func (s *omniBuf) Version() string        { return ModuleVersion("github.com/omnibuf/omnibuf-go") }
func (s *omniBuf) StreamMode() StreamMode { return StreamAdapted }
func (s *omniBuf) NativeKind() NativeKind { return NativeMessage }
func (s *omniBuf) Supports(n string) bool {
	return modelv2.IsV2TypeName(n)
}

func (s *omniBuf) Prepare(fx model.Fixture) error {
	s.fxName = fx.Name
	s.project = fx.Name == "table_project"
	p, err := toProto(fx)
	if err != nil {
		return err
	}
	msg, ok := p.(omniWireMessage)
	if !ok {
		return fmt.Errorf("omnibuf: %T does not implement omniWireMessage", p)
	}
	dst, ok := p.ProtoReflect().New().Interface().(omniWireMessage)
	if !ok {
		return fmt.Errorf("omnibuf: %T does not implement omniWireMessage", p)
	}
	_, s.batch = p.(*pbv2.BatchTable)
	s.msg = msg
	s.dst = dst
	s.serBuf = s.serBuf[:0]
	return nil
}

func (s *omniBuf) SerializeBytes(_ model.Fixture) ([]byte, error) {
	if s.msg == nil {
		return nil, fmt.Errorf("omnibuf: prepare() required before serialize")
	}
	s.serBuf = s.msg.MarshalOmniBufAppend(s.serBuf[:0])
	out := make([]byte, len(s.serBuf))
	copy(out, s.serBuf)
	return out, nil
}

func (s *omniBuf) DeserializeBytes(buf []byte) (any, error) {
	if s.dst == nil {
		return nil, fmt.Errorf("omnibuf: prepare() required before deserialize")
	}
	if s.project {
		if !s.batch {
			var ot pbv2.OpaqueTable
			if err := ot.Unmarshal(buf); err != nil {
				return nil, err
			}
			return []float64{ot.GetFFloat_0()}, nil
		}
		var obt pbv2.OpaqueBatchTable
		if err := obt.Unmarshal(buf); err != nil {
			return nil, err
		}
		out := make([]float64, 0, obt.ItemsLen())
		for _, row := range obt.IterItems() {
			out = append(out, row.GetFFloat_0())
		}
		return out, nil
	}
	if err := s.dst.UnmarshalOmniBuf(buf, false); err != nil {
		return nil, err
	}
	return s.dst, nil
}

func (s *omniBuf) ToDomain(decoded any) (any, error) {
	if s.project {
		if vals, ok := decoded.([]float64); ok {
			return vals, nil
		}
	}
	msg, ok := decoded.(proto.Message)
	if !ok {
		return decoded, nil
	}
	return fromProto(s.fxName, msg)
}

func (s *omniBuf) SerializeStream(fx model.Fixture, w io.Writer) (int, error) {
	return AdaptedSerializeStream(s, fx, w)
}

func (s *omniBuf) DeserializeStream(r io.Reader) (any, error) {
	return AdaptedDeserializeStream(s, r)
}
